_DEB_NOMS = {s: n for s, n, *_ in _DV}
for _i, (slug, nom, dep, lead, local) in enumerate(_DV):
    path = "/debarras-%s/" % slug
    if path in P:
        continue
    secs = [local] + [_DPOOL[j] for j in _DCOMBOS[_i % len(_DCOMBOS)]]
    _d = _DIOG[_i % len(_DIOG)]
    secs.append((_d[0] % {"nom": nom}, _d[1] % {"nom": nom}))
    secs.append(("Mon intervention à %s" % nom, _DFIN[_i % len(_DFIN)] % {"nom": nom}))
    faq = [("Intervenez-vous dans un cas de syndrome de Diogène ?",
            "Oui, régulièrement. Je viens voir sans juger, je peux travailler par étapes, et le traitement des nuisibles fait partie du chantier. J'interviens à la demande de la personne comme d'un proche, d'un tuteur, d'un bailleur ou d'un syndic.")] \
          + [_DFAQ[j] for j in _DFCOMBOS[_i % len(_DFCOMBOS)] if _DFAQ[j][0] != "Intervenez-vous dans un cas de syndrome de Diogène ?"]
    svc = [("Tout sur le débarras", "/debarras/")]
    for p2, lib in (("/deratisation-%s/" % slug, "Dératisation à %s" % nom),
                    ("/punaises-de-lit-%s/" % slug, "Punaises de lit à %s" % nom),
                    ("/frelons-guepes-%s/" % slug, "Nid de frelons à %s" % nom)):
        if p2 in P:
            svc.append((lib, p2))
    svc += [("Blattes et cafards", "/blattes-cafards/"), ("Piégeur agréé", "/piegeur-agree/")]
    vois = [(n, "/debarras-%s/" % s) for s, n, *_ in _DV[max(0, _i - 2):_i] + _DV[_i + 1:_i + 3]]
    links = [("Autres services à %s" % nom, svc)]
    if vois:
        links.append(("Communes voisines", [("Débarras à %s" % n, u) for n, u in vois]))
    links.append(("Voir aussi", [("Agences et syndics", "/agences-syndics/"), ("Zones d'intervention", "/zones-intervention/"),
                                 ("Particuliers", "/particuliers/"), ("Devis et contact", "/contact/")]))
    _t = "Débarras %s (%s) | Proxinuisibles" % (nom, dep)
    if len(_t) > 60:
        _t = "Débarras %s | Proxinuisibles" % nom
    _m = "Débarras de maison, cave, grenier et dépendance à %s (%s), avec traitement des nuisibles dans le même passage. Devis gratuit." % (nom, dep)
    if len(_m) > 155:
        _m = "Débarras de maison, cave et grenier à %s (%s), avec traitement des nuisibles. Devis gratuit." % (nom, dep)
    add(path, h1="Débarras à %s (%s) : maison, cave, grenier et dépendance" % (nom, dep),
        title=_t, meta=_m, lead=lead, secs=secs, faq=faq, links=links, kind="ville")

P["/debarras/"]["links"].insert(0, ("Le débarras, commune par commune",
    [("Débarras à %s" % n, "/debarras-%s/" % s) for s, n, *_ in _DV]))
P["/zones-intervention/"]["links"].append(("Débarras, commune par commune",
    [("Débarras %s" % n, "/debarras-%s/" % s) for s, n, *_ in _DV]))
